/// The fields each Material constant is built with (Java: the enum constructor).
pub struct MaterialData {
    pub id: i32,
    pub name: Option<String>,
    /// `Constructor<? extends MaterialData>`: `data`'s `(Material, byte)` constructor when `data` is a
    /// `MaterialData` class.
    pub ctor: Option<fn(Material, i8) -> JRef<dyn MaterialDataTrait>>,
    pub data: crate::rt::Class,
    pub legacy: bool,
    pub key: JRef<NamespacedKey>,
    /// `Suppliers.memoize(...)` (computed by `as_item_type`).
    pub item_type: std::sync::OnceLock<Option<JRef<dyn ItemType>>>,
    /// `Suppliers.memoize(...)` (computed by `as_block_type`).
    pub block_type: std::sync::OnceLock<Option<JRef<dyn BlockType>>>,
}
/// Java: `private Material(final int id, final crate::rt::Class data, final String name)` (the shorter
/// constructors pass `MaterialData.class` and `null`).
fn md(
    this: Material,
    id: i32,
    data: crate::rt::Class,
    ctor: Option<fn(Material, i8) -> JRef<dyn MaterialDataTrait>>,
    name: Option<&str>,
) -> MaterialData {
    let legacy = this.name().starts_with(LEGACY_PREFIX);
    let key = NamespacedKey::minecraft(&this.name().to_lowercase());
    // try to cache the constructor for this material: `ctor` is `data.getConstructor(Material.class, byte.class)`
    // when `MaterialData.class.isAssignableFrom(data)`, else null (resolved by the table below)
    MaterialData {
        id,
        data,
        name: name.map(|s| s.to_string()),
        legacy,
        key,
        ctor,
        item_type: std::sync::OnceLock::new(),
        block_type: std::sync::OnceLock::new(),
    }
}
